'use strict';

// MODULES //

var canonicalStringify = require( '@data-apis/canonical/stringify' );


// FUNCTIONS //

/**
* Asserts that a value is a bounded, trimmed string.
*
* @private
* @param {*} value - value
* @param {string} field - field name
*/
function boundedString( value, field ) {
	if ( typeof value !== 'string' || value.length === 0 || value.length > 512 || value !== value.trim() ) {
		throw new Error( 'Provider adapter returned invalid ' + field );
	}
}


// MAIN //

/**
* Validates provider-neutral CI provenance before downstream use.
*
* @param {Object} origin - origin object
* @returns {Object} validated origin
*/
function validateNeutralOrigin( origin ) {
	var allowed = new Set( ['type', 'provider', 'project', 'ref', 'run', 'artifact', 'provider_details'] );
	var serialized;

	if ( !origin || origin.type !== 'ci_artifact' ) {
		throw new Error( 'Provider adapter returned an invalid origin type' );
	}
	Object.keys( origin ).forEach( function validateKey( key ) {
		if ( !allowed.has( key ) ) {
			throw new Error( 'Provider adapter returned unrecognized origin field: ' + key );
		}
	} );
	boundedString( origin.provider, 'provider' );
	boundedString( origin.project && origin.project.id, 'project.id' );
	boundedString( origin.project && origin.project.locator, 'project.locator' );
	boundedString( origin.ref && origin.ref.kind, 'ref.kind' );
	boundedString( origin.ref && origin.ref.name, 'ref.name' );
	boundedString( origin.run && origin.run.id, 'run.id' );
	if ( origin.run && origin.run.revision !== undefined ) {
		boundedString( origin.run.revision, 'run.revision' );
	}
	boundedString( origin.artifact && origin.artifact.name, 'artifact.name' );
	if ( origin.artifact && origin.artifact.id !== undefined ) {
		boundedString( origin.artifact.id, 'artifact.id' );
	}
	serialized = canonicalStringify( origin ).toLowerCase();
	['authorization', 'cookie', 'x-amz-signature', 'x-goog-signature'].forEach( function forbid( name ) {
		if ( serialized.includes( name ) ) {
			throw new Error( 'Provider origin contains forbidden credential material: ' + name );
		}
	} );
	return origin;
}


// EXPORTS //

module.exports = validateNeutralOrigin;
